public class Ex04CustomExceptionChain {
    static class ServiceException extends Exception {
        ServiceException(String msg, Throwable cause) { super(msg, cause); }
    }
    public static void main(String[] args) {
        try {
            try {
                throw new IllegalStateException("db connection lost");
            } catch (IllegalStateException root) {
                throw new ServiceException("failed to load user", root);
            }
        } catch (ServiceException e) {
            System.out.println("message=" + e.getMessage());
            System.out.println("cause=" + e.getCause());
            System.out.println("cause message=" + e.getCause().getMessage());
        }
    }
}
